def reachable_stops(routes, depot):
    """Courier route reachability terminates even when a cycle returns to the depot."""
    visited = {depot}
    pending = list(routes.get(depot, []))
    while pending:
        stop = pending.pop()
        if stop not in visited:
            visited.add(stop)
            pending.extend(routes.get(stop, []))
    return sorted(visited - {depot})

