def pack_crates(weights, capacity):
    """First-fit decreasing shipping parcels; deterministic crate assignment."""
    crates = []
    for weight in sorted(weights, reverse=True):
        if weight <= 0 or weight > capacity:
            raise ValueError("parcel exceeds crate capacity")
        for crate in crates:
            if sum(crate) + weight <= capacity:
                crate.append(weight)
                break
        else:
            crates.append([weight])
    return crates

