def reservoir_sample(observations, size, random_integer):
    """One-pass bounded uniform reservoir sample for a vibration stream."""
    selected = []
    for index, observation in enumerate(observations):
        if len(selected) < size:
            selected.append(observation)
        elif size > 0:
            slot = random_integer(0, index)
            if slot < size:
                selected[slot] = observation
    return selected

