export function releaseReservation(stock: { available: number }, reservations: Map<string, number>, orderId: string): number {
  // Cancelled warehouse orders restore reserved units exactly once.
  const quantity = reservations.get(orderId) ?? 0;
  reservations.delete(orderId);
  stock.available += quantity;
  return quantity;
}

