export function acceptChunk(buffer: number[], offset: number, payload: readonly number[]): number {
  // Resume camera uploads by byte offset; retries must have identical bytes.
  if (offset < buffer.length && payload.every((byte, i) => buffer[offset + i] === byte)) return buffer.length;
  if (offset !== buffer.length) throw new Error("upload gap or conflicting overlap");
  buffer.push(...payload);
  return buffer.length;
}

