export function reachableStops(routes: Record<string, string[]>, depot: string): string[] {
  // Courier route reachability terminates even when a cycle returns to the depot.
  const visited = new Set([depot]);
  const pending = [...(routes[depot] ?? [])];
  while (pending.length) {
    const stop = pending.pop()!;
    if (!visited.has(stop)) { visited.add(stop); pending.push(...(routes[stop] ?? [])); }
  }
  return [...visited].filter(stop => stop !== depot).sort();
}

