export function scrubDiagnostic(value: unknown): unknown {
  // Recursively redact credentials in exported diagnostics without mutation.
  if (Array.isArray(value)) return value.map(scrubDiagnostic);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) =>
      [key, ["password", "access_token"].includes(key) ? "[redacted]" : scrubDiagnostic(item)]));
  }
  return value;
}

