export function packCrates(weights: readonly number[], capacity: number): number[][] {
  // First-fit decreasing shipping parcels; deterministic crate assignment.
  const crates: number[][] = [];
  for (const weight of [...weights].sort((a, b) => b - a)) {
    if (weight <= 0 || weight > capacity) throw new Error("parcel exceeds crate capacity");
    const crate = crates.find(items => items.reduce((sum, item) => sum + item, 0) + weight <= capacity);
    if (crate) crate.push(weight); else crates.push([weight]);
  }
  return crates;
}

