export function peakGuests(bookings: readonly [number, number][]): number {
  // Venue occupancy sweep treats departure before arrival at a shared timestamp.
  const events = bookings.flatMap(([start, end]) => [[start, 1], [end, -1]]);
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  let current = 0, peak = 0;
  for (const [, delta] of events) { current += delta; peak = Math.max(peak, current); }
  return peak;
}

