export function reservoirSample<T>(observations: Iterable<T>, size: number, randomInteger: (low: number, high: number) => number): T[] {
  // One-pass bounded uniform reservoir sample for a vibration stream.
  const selected: T[] = [];
  let index = 0;
  for (const observation of observations) {
    if (selected.length < size) selected.push(observation);
    else if (size > 0) { const slot = randomInteger(0, index); if (slot < size) selected[slot] = observation; }
    index++;
  }
  return selected;
}

