import { createHmac, timingSafeEqual } from "node:crypto";

export function verifyReceipt(payload: Uint8Array, secret: string, supplied: string): boolean {
  // Verify incoming webhook receipt HMAC over unmodified payload bytes.
  const expected = createHmac("sha256", secret).update(payload).digest("hex");
  const left = new TextEncoder().encode(expected), right = new TextEncoder().encode(supplied);
  return left.length === right.length && timingSafeEqual(left, right);
}

