export function nextVehicle<T extends { urgency: number }>(queue: T[]): T | undefined {
  // Emergency dispatch prioritizes urgency, retaining insertion order for ties.
  if (!queue.length) return undefined;
  let best = 0;
  for (let i = 1; i < queue.length; i++) if (queue[i].urgency > queue[best].urgency) best = i;
  return queue.splice(best, 1)[0];
}

